mapper.select:
select g.*,(select count(*) from room r where r.goods_id=g.goods_id) as counts from goods g where 1=1
and g.tearoom_id like concat('%',#{tearoomId},'%')
and g.goods_category = #{goodsCategory}
and g.status = #{status}
and g.goods_name like concat('%',#{goodsName},'%')
order by g.sort
